/* 按 DRG 编码取配置；未配置则取兜底 */
function weightOf(code) {
  const c = DRG_WEIGHTS.map[code] || DRG_WEIGHTS.default;
  return { rw: c.rw, drugRate: c.drugRate, materialRate: c.materialRate, checkRate: c.checkRate };
}
